const e={subtitle:"Klim hoger, ontwijk obstakels, ontgrendel legendarische skins en ga de strijd aan met spelers wereldwijd.",download:"Download op Google Play",download_apple:"Binnenkort in de App Store",f1_title:"Één-tik gameplay",f1_desc:'Tik om te vliegen. Bruut eenvoudig, eindeloos diep. Het soort spel waarbij je 40 minuten lang zegt "nog één keer".',f2_title:"Pixel Art",f2_desc:"Handgemaakte retro visuals met soepele animaties. Elke skin en achtergrond heeft zijn eigen persoonlijkheid.",f3_title:"Wereldwijd concurreren",f3_desc:"Verbeter je highscore en ga de strijd aan met spelers wereldwijd op het globale klassement.",fv_shop_eyebrow:"In-game winkel",fv_shop_title:"Pas alles aan",fv_shop_desc:"De winkel laat je ver voorbij het standaard uiterlijk gaan. Ontgrendel nieuwe vogelskims, obstakelstijlen en geanimeerde achtergronden — alles verdiend met credits die je in het spel verzamelt. Geen echt geld vereist.",fv_shop_pill1:"Vogel skins",fv_shop_pill2:"Obstakel skins",fv_shop_pill3:"Achtergronden",fv_shop_pill4:"Verdien door te spelen",fv_boost_eyebrow:"Boosters",fv_boost_title:"Keer het tij midden in een run",fv_boost_desc:"Moeite met een run? Activeer een booster om door te gaan. Bescherm jezelf, vertraag de tijd, krimp om door gaten te glippen, magnetiseer je score of trek nabijgelegen objecten aan om te overleven.",fv_boost_pill1:"Schild",fv_boost_pill2:"Slow motion",fv_boost_pill3:"Krimpen",fv_boost_pill4:"Score magneet",fv_boost_pill5:"Object magneet",fv_rewards_eyebrow:"Beloningssysteem",fv_rewards_title:"Altijd iets om naar te streven",fv_rewards_desc:"Dagelijkse missies vernieuwen zich elke dag met nieuwe doelstellingen die je credits opleveren. Houd je reeks bij, ontgrendel progressiemijlpalen en zoek naar verborgen geheime beloningen in het spel.",fv_rewards_pill1:"Dagelijkse missies",fv_rewards_pill2:"Reekssysteem",fv_rewards_pill3:"Progressie",fv_rewards_pill4:"Geheime beloningen",fv_social_eyebrow:"Account & vrienden",fv_social_title:"Speel met vrienden, versla hun score",fv_social_desc:"Maak een gratis account aan om je voortgang op alle apparaten op te slaan, voeg vrienden toe en vergelijk scores op een speciaal vriendenklassement. Wie is echt de beste onder jullie?",fv_social_pill1:"Globaal klassement",fv_social_pill2:"Vriendenklassement",fv_social_pill3:"Persoonlijk record",fv_social_pill4:"Sync op alle apparaten",fv_extra_title:"Meer redenen om te blijven spelen",fv_extra_label:"En meer",fv_extra1_title:"Herleef je run",fv_extra1_desc:"Bekijk een korte advertentie om direct te herleven als je run eindigt — of gebruik opgeslagen credits om door te gaan zonder advertentie.",fv_extra2_title:"Kijk & verdien",fv_extra2_desc:"Te weinig credits? Bekijk een snelle advertentie om direct +200 credits te verdienen en skins en boosters sneller te ontgrendelen.",fv_extra3_title:"Ga premium",fv_extra3_desc:"Verwijder alle advertenties en ontvang een creditbonus. Speel zonder onderbrekingen en steun de solo-ontwikkelaar achter het spel.",fv_extra4_title:"100% gratis om te starten",fv_extra4_desc:"Geen betaalmuren. Elke skin, booster en achtergrond is te verdienen door gewoon te spelen. Download en begin.",fv_cta_label:"Nu beschikbaar",fv_cta_title:"Klaar om het klassement te domineren?",fv_cta_sub:"Gratis te downloaden. Geen account nodig om te beginnen met vliegen.",fv_cta_btn:"Gratis downloaden op Google Play",fv_stat1_num:"Gratis",fv_stat1_lbl:"te spelen",fv_stat2_num:"3+",fv_stat2_lbl:"Skin categorieën",fv_stat3_num:"5+",fv_stat3_lbl:"Boosters",fv_stat4_lbl:"Globaal klassement",bd_subtitle:"Beheers de zwaartekracht, schuif de blokken en los de ultieme puzzeluitdaging op.",bd_stat1_num:"2000+",bd_stat1_lbl:"Niveaus",bd_stat2_num:"2",bd_stat2_lbl:"Rastertypen",bd_stat3_num:"4",bd_stat3_lbl:"Visuele thema's",bd_stat4_lbl:"Gratis",bd_adv_eyebrow:"Avonturenmodus",bd_adv_title:"2000+ handgemaakte niveaus",bd_adv_desc:"Twee volledige avonturenmodi om te veroveren: het klassieke vierkante raster met 1000 niveaus, en het unieke hexagonale Hex Drift-raster — ook 1000 niveaus. Kies tussen zwaartekrachtmodus of zonder zwaartekracht voor elk.",bd_adv_pill1:"1000 klassieke niveaus",bd_adv_pill2:"1000 Hex Drift niveaus",bd_adv_pill3:"Met & zonder zwaartekracht",bd_adv_pill4:"Sectorprogressie",bd_game_eyebrow:"Gameplay",bd_game_title:"Schuif, val, combo",bd_game_desc:"Sleep gekleurde blokstukken op het raster om volledige rijen te vormen en te wissen. Zwaartekracht verandert alles — stukken vallen en stapelen anders afhankelijk van de modus. Ketting zetten voor combo's en hogere scores.",bd_game_pill1:"Zwaartekrachtmechanica",bd_game_pill2:"Combosysteem",bd_game_pill3:"Vierkant & hexagonaal raster",bd_game_pill4:"Standaard, Ster, Rots & Staal blokken",bd_endless_eyebrow:"Eindeloos & Dagelijks",bd_endless_title:"Elke dag een nieuwe uitdaging",bd_endless_desc:"De eindeloze modus laat je records najagen onder zwaartekracht zonder niveaulimiet. De dagelijkse uitdaging vernieuwt elke dag met 5 fasen van toenemende moeilijkheid — voltooi ze allemaal voor een beloning.",bd_endless_pill1:"Eindeloze modus",bd_endless_pill2:"Dagelijkse uitdaging",bd_endless_pill3:"5 fasen / dag",bd_endless_pill4:"Dagelijkse beloningen",bd_collect_eyebrow:"Collectie",bd_collect_title:"Ontgrendel thema's & blokskins",bd_collect_desc:"Verzamel 9 kleuren × 8 blokvormen verspreid over 4 visuele stijlen — Klassiek, Neon, Pastel en Snoep. Ontgrendel door te levelen en sterren te verdienen. Jouw raster, jouw look.",bd_collect_pill1:"9 kleuren × 8 vormen",bd_collect_pill2:"Klassiek thema",bd_collect_pill3:"Neon thema",bd_collect_pill4:"Pastel & Snoep",bd_extra_label:"En meer",bd_extra_title:"Alles wat je moet weten",bd_extra1_title:"Premium toegang",bd_extra1_desc:"Verwijder alle advertenties en geniet van een ononderbroken puzzelervaring. Een eenmalige aankoop die de solo-ontwikkelaar steunt.",bd_extra2_title:"Levens systeem",bd_extra2_desc:"Je hebt 5 levens om te besteden tussen niveaus. Op? Bekijk een advertentie om bij te vullen, wacht tot ze herladen — of ga premium.",bd_extra3_title:"Zen modus",bd_extra3_desc:"Elke sector heeft ook een Zen-variant — zelfde indeling, geen timer, geen druk. Focus puur op de puzzel.",bd_extra4_title:"Gratis te spelen",bd_extra4_desc:"Download en speel vanaf niveau 1 gratis. Alle niveaus, beide rasters, alle modi — geen betaalmuur om te beginnen.",bd_cta_label:"Nu beschikbaar",bd_cta_title:"Klaar om de zwaartekracht te beheersen?",bd_cta_sub:"Gratis te downloaden. 2000+ niveaus wachten op je.",bd_cta_btn:"Gratis downloaden op Google Play",play_online:"Online spelen (Web)",copyright:"&copy; 2026 AC Games. Alle rechten voorbehouden.",privacy:"Privacybeleid",contact:"Contact Support",delete_account:"Verzoek om Accountverwijdering",home_title:"AC Games",home_subtitle:"Mobiele spellen gebouwd voor de vreugde van het spelen.",home_eyebrow:"Indie game studio",nav_home:"Home",nav_about:"Over Mij",nav_tech:"Technologieën",nav_games:"Spellen",nav_contact:"Contact",about_title:"Over Mij",about_desc:"Ik ben Clement — solo-ontwikkelaar, gamer in hart en nieren. Ik maak mobiele spellen die belachelijk eenvoudig zijn om te starten en onmogelijk om te stoppen. Flappy Vertical was nog maar het begin. Block Drift is er al, en ik ben nog lang niet klaar.",tech_title:"Technologieën die ik gebruik",games_title:"Spellen",game_flappy_title:"Flappy Vertical",game_flappy_desc:"De verticale draai aan een klassieker!",game_flappy_platform:"Android",game_new_title:"Slice and Trap",game_new_desc:"Een gemoderniseerde versie van JezzBall met boosters en een winkel.",game_new_platform:"Binnenkort 2026",game_block_drift_title:"Block Drift",game_block_drift_desc:"Een op zwaartekracht gebaseerde blokpuzzeluitdaging.",game_block_drift_platform:"Android",coming_soon:"Binnenkort beschikbaar",live_badge:"Live op Android",contact_title:"Neem Contact Op",contact_name:"Naam",contact_email:"E-mail",contact_message:"Bericht",contact_send:"Verzend Bericht",contact_game:"Gerelateerd spel",contact_game_none:"Geen / Algemeen",contact_subject:"Onderwerp",contact_subj_question:"Algemene vraag",contact_subj_bug:"Bug melden",contact_subj_feedback:"Feedback / Suggestie",contact_subj_other:"Overig",s1_title:"Strategische Puzzels",s1_desc:"Vang de stuiterende ballen door de arena te snijden. Plan je sneden zorgvuldig!",s2_title:"Boosters",s2_desc:"Gebruik speciale power-ups om de tijd te bevriezen, je lijnen te verlengen, en meer.",s3_title:"In-Game Winkel",s3_desc:"Ontgrendel aangepaste bal skins, nieuwe snij-animaties, en kleurrijke arena's.",bd1_title:"Zwaartekrachtmechanica",bd1_desc:"Ervaar een unieke draai aan blokpuzzels waarbij de zwaartekracht alles verandert.",bd2_title:"100+ Niveaus",bd2_desc:"Daag jezelf uit met meer dan 100 handgemaakte zwaartekrachtpuzzels in de avontuurmodus.",bd3_title:"Eindeloze Modus",bd3_desc:"Test je overlevingsvaardigheden in een oneindige uitdaging. Hoe lang hou jij het vol?",form_success:"Bericht succesvol verzonden! We nemen spoedig contact met u op.",form_send_error:"Kon bericht niet verzenden. Probeer het later opnieuw.",form_error:"Vul alle verplichte velden in.",cookie_text:"We gebruiken cookies om ervoor te zorgen dat u de beste ervaring op onze website krijgt.",cookie_accept:"Begrepen!",captcha_error:"Voltooi de beveiligingscontrole.","404_title":"Pagina Niet Gevonden","404_message":"Sorry, de pagina die u zoekt kon niet worden gevonden.","404_button":"Ga naar de Homepage",hero_title:"Mobiele spellen gemaakt met passie",hero_see_games:"Bekijk onze spellen",about_title_name:"AC Games",about_card1_title:"Solo-ontwikkelaar",about_card1_desc:"Elke regel code, elke pixel, elke ontwerpbeslissing — gedaan door één persoon.",about_card2_title:"Mobiel eerst",about_card2_desc:"Gebouwd voor Android, ontworpen voor de snelle sessie die je niet wilt stoppen.",about_card3_title:"Altijd aan het bouwen",about_card3_desc:"2 spellen live, 1 in voorbereiding. Nieuwe mechanica, nieuwe uitdagingen, altijd leveren.",stat_games:"Spellen",stat_live:"Live op Android",stat_new:"Nieuwe releases",share_game:"Deel dit spel",play_itchio:"Speel op itch.io",games_header_title:"Mijn Spellen",tech_built_with:"Gemaakt met",features_label:"Functies",features_title:"Functies",waitlist_placeholder:"jouw@email.com",waitlist_button:"Stuur me een notificatie bij lancering",waitlist_label:"Geen spam. Eén e-mail wanneer het uitkomt.",contact_desc:"Heb je een bug te melden, een vraag over een van onze spellen, of wil je gewoon hallo zeggen? Ik ben een solo dev — ik lees elk bericht.",contact_game_support:"Game Support",contact_game_support_desc:"Problemen met Flappy Vertical of Block Drift? Beschrijf het probleem en je apparaat.",contact_deletion_desc:"Gebruik het verwijderingsformulier voor snellere verwerking.",contact_response_time:"Responstijd",contact_response_time_desc:"Meestal binnen 24–48 uur op werkdagen.",privacy_title:"Privacybeleid",privacy_eyebrow:"Wettelijk",privacy_meta:"Laatste update: 4 januari 2026",toc_title:"Op deze pagina",toc_1:"1. Informatie die we verzamelen",toc_2:"2. Hoe we uw informatie gebruiken",toc_3:"3. Gegevensdeling",toc_4:"4. Gegevensbeveiliging",toc_5:"5. Privacy van kinderen",toc_6:"6. Uw rechten",toc_7:"7. Wijzigingen in dit beleid",toc_8:"8. Neem contact met ons op",privacy_highlight:"Je privacy is belangrijk voor ons. Onze spellen zijn ontworpen om leuk te zijn, en we streven naar transparantie over de gegevens die worden verwerkt wanneer je ze speelt.",privacy_intro:'Dank je voor het spelen van onze spellen. Dit Privacybeleid legt uit hoe we informatie verwerken wanneer je onze mobiele applicaties (de "Spellen") gebruikt.',privacy_s1_title:"1. Informatie die we verzamelen en waarom",privacy_s1_p1:"Om onze Spellen te leveren en te verbeteren, gebruiken we services van derden die informatie kunnen verzamelen.",privacy_firebase:"A. Firebase (Google)",privacy_firebase_p1:"We gebruiken Firebase voor essentiële spelenfunctionaliteiten:",privacy_firebase_li1:"Firebase Authentication — om je in staat te stellen een account aan te maken (via Google Sign-In of email/wachtwoord) en je voortgang veilig op te slaan. Dit verwerkt je e-mailadres, een gebruikers-ID en verificatietokens.",privacy_firebase_li2:"Cloud Firestore — om je spelgegevens op te slaan, zoals hoge scores, tegoeden, ontgrendelde items en vriendenlijsten, gekoppeld aan je gebruikers-ID.",privacy_firebase_li3:"Firebase Crashlytics — om crashes te detecteren en analyseren. Dit verzamelt informatie met betrekking tot crashes, inclusief apparaattoestand, type en OS om ons bugs te helpen repareren. Het verzamelt geen persoonsgegevens.",privacy_admob:"B. Google AdMob",privacy_admob_p1:"We gebruiken Google AdMob om advertenties weer te geven. AdMob kan gegevens verzamelen en gebruiken om gepersonaliseerde advertenties te leveren, waaronder:",privacy_admob_li1:"Apparaatidentificaties (zoals de Advertising ID).",privacy_admob_li2:"Locatiegegevens (als locatieservices zijn ingeschakeld).",privacy_admob_li3:"Informatie over je interacties met advertenties.",privacy_admob_optout:'Je kunt je advertentievoorkeur beheren in de instellingen van je apparaat — "Advertentie-tracking beperken" op iOS of "Opt-out van advertentiepersonalisatie" op Android.',privacy_s2_title:"2. Hoe we uw informatie gebruiken",privacy_s2_li1:"Om de Spellen te exploiteren en onderhouden (bijv. je scores opslaan).",privacy_s2_li2:"Om bugs op te sporen en de gebruikerservaring te verbeteren (via Crashlytics).",privacy_s2_li3:"Om de Spellen financieel te ondersteunen via advertenties (via AdMob).",privacy_s2_li4:"Om sociale functies zoals rankings en vriendenlijsten te bieden.",privacy_s3_title:"3. Gegevensdeling",privacy_s3_p1:"We delen je persoonlijke gegevens niet handmatig met derden, behalve voor gegevens die automatisch door de bovengenoemde services (Firebase en AdMob) worden verzameld als onderdeel van hun normale werking.",privacy_s4_title:"4. Gegevensbeveiliging",privacy_s4_p1:"We treffen redelijke maatregelen om je informatie te beschermen. Gegevens die op Firebase zijn opgeslagen, worden beveiligd door de infrastructuur van Google. Echter, geen methode van transmissie via het internet of elektronische opslag is 100% veilig.",privacy_s5_title:"5. Privacy van kinderen",privacy_s5_p1:"Onze Spellen zijn niet bedoeld voor kinderen onder de 13 jaar. We verzamelen niet bewust persoonlijke informatie van kinderen onder de 13 jaar. Als je denkt dat we dergelijke informatie per ongeluk hebben verzameld, neem dan contact met ons op zodat we deze onmiddellijk kunnen verwijderen.",privacy_s6_title:"6. Uw rechten",privacy_s6_p1:"Afhankelijk van je locatie (bijv. als je in de Europese Unie bent), heb je mogelijk rechten met betrekking tot je persoonlijke gegevens, zoals het recht op toegang, correctie of verwijdering van je gegevens. Onze Spellen bieden een in-app functie om je account te verwijderen. Je kunt ook het aanvraagformulier voor accountverwijdering gebruiken.",privacy_s7_title:"7. Wijzigingen in dit privacybeleid",privacy_s7_p1:"We kunnen dit Privacybeleid van tijd tot tijd bijwerken. We zullen je op de hoogte stellen van wijzigingen door het nieuwe Privacybeleid in het Spel of op onze website te plaatsen. We raden je aan dit beleid regelmatig door te nemen.",privacy_s8_title:"8. Neem contact met ons op",privacy_s8_p1:"Als je vragen hebt over dit Privacybeleid, neem dan contact met ons op via de ondersteuningsfunctie in het spel of via onze contactpagina."};export{e as translations_nl};
